statement.raw_tex:
\begin{restatable}{theorem}{proprobustmaxtractable}\label{prop_robust_max_tractable} 
sDFO \eqref{robust_max_b} can be tractable if any of the following conditions holds:
\begin{itemize}
\item[(i)] When $ \bm a_k(\bm x):=\bar{\bm a}_k$ is constant for all $k\in[K]$ and $\bm{x}\in \X$,  sDFO \eqref{robust_max_b} is equivalent to
\begin{align*}
v^*=\min_{\bm x\in\X,\rxi,\eta}  \left\{\eta\colon\eta\geq \rxi^\top \bar{\bm a}_k+b_k(\bm x), \forall k\in[K], \|\rxi-\rxi^0\|_p\leq \theta\right\};
\end{align*}
\item[(ii)] When $p=1$ and  $a_k(\bm x)=a_1(\bm x)$ for each $k\in[K]$, sDFO  \eqref{robust_max_b} is equivalent to solving $2m$ tractable convex programs, and selecting the lowest optimal value, i.e., $v^*=\min_{i\in[m],\ell\in [2]}v_{i\ell}^*$, where for each $i\in[m]$, we have
\begin{align*}
& v_{i1}^*=\min_{\bm x\in\X,\eta}  \left\{\eta\colon \eta\geq  b_k(\bm x)+ {\rxi^0}^\top \bm a_1(\bm x)- \theta a_{1i}(\bm x),\forall k\in[K] \right\},\\
& v_{i2}^*=\min_{\bm x\in\X,\eta}  \left\{\eta\colon \eta\geq  b_k(\bm x)+ {\rxi^0}^\top \bm a_1(\bm x) + \theta a_{1i}(\bm x),\forall k\in[K] \right\};
\end{align*}
\item[(iii)] Suppose that $p=1$,  and $\rxi:=[\rxi_1,\ldots,\rxi_K]$ such that $\rxi^i$ and $\rxi^j$ do not overlap for each $i\neq j$, and $\rxi^\top \bm a_k(\bm x)= {\rxi^k}^\top \bar{\bm a}_{k}(\bm x) $ for each $k\in[K]$ such that $\|\bar{\bm a}_k(\bm x) \|_{\infty}=C_k$ is constant for each $k\in[K]$, where $\rxi_k\in \Re^{m_k}$, $\bar{\bm a}_k(\bm x)=\bar{\bm{A}}_k \bm{x}+\bar{\bm a}_k\in \Re^{m_k}$ with $\bar{\bm{A}}_k\in \Re^{m_k\times n},\bar{\bm a}_k\in \Re^{m_k}$ such that $\bar{\bm{A}}_i$ and $\bar{\bm{A}}_j$, $\bar{\bm{a}}_i$ and $\bar{\bm{a}}_j$ do not overlap each $i\neq j$ with $\sum_{k\in[K]}m_k=m$ and each $m_k$ is nonnegative. 
Then,  sDFO \eqref{robust_max_b} is equivalent to solving
\begin{align*}
v^*=\min_{\bm x\in\X,\beta,\bm\gamma\geq \bm 0} \left\{\beta\colon \sum_{k\in[K]} \gamma_{k}= \theta,\beta \geq  {\rxi_k^0}^\top \bar{\bm a}_{k}(\bm x)+b_k(\bm x)-\gamma_{k}C_k,\forall k\in[K]  \right\}.
\end{align*}
\end{itemize}
\end{restatable}

