\begin{proof}
Let us first consider the inner minimax of sDFO \eqref{robust_max_b} as
\begin{align*}
\min_{\rxi} \left\{\max_{k\in[K]}  \rxi^\top \bm a_k(\bm x)+b_k(\bm x)\colon \|\bm \xi-\bm \xi^0\|_p\leq \theta\right\}.
\end{align*}
Introducing auxiliary nonnegative variables $\bm\lambda$, the inner minimax of sDFO \eqref{robust_max_b} is equivalent to
\begin{align*}
\min_{\rxi}\left\{\max_{\bm\lambda\geq  \bm 0}\left\{\sum_{k\in[K]} \lambda_k \left[{\rxi}^\top \bm a_k(\bm x)+b_k(\bm x)\right]\colon  \sum_{k\in[K]} \lambda_k =1\right\}: \|\bm \xi-\bm \xi^0\|_p\leq \theta\right\}.
\end{align*} 
According to Sion's minimax theorem \cite{sion1958general}, we can interchange the maximum operator with the minimum one as
\begin{align*}
\max_{\bm\lambda\geq  \bm 0}\left\{\min_{\rxi}\left\{\sum_{k\in[K]} \lambda_k \left[{\rxi}^\top \bm a_k(\bm x)+b_k(\bm x)\right]\colon \|\bm \xi-\bm \xi^0\|_p\leq \theta  \right\}:\sum_{k\in[K]} \lambda_k =1\right\}.
\end{align*}
Invoking the definition of dual norm, we have 
\begin{align*}
\max_{\bm\lambda\geq  \bm 0}\left\{\sum_{k\in[K]} \lambda_k \left[{\rxi^0}^\top \bm a_k(\bm x) +b_k(\bm x) \right] -  \theta \left\|\sum_{k\in[K]} \lambda_k \bm a_k(\bm x) \right\|_{p^*}  \colon  \sum_{k\in[K]} \lambda_k =1 \right\}.
\end{align*}
